  "literacy.tutorial.subtitle": "کٲریگرن خٲطرٕ ڈیزائن کرنہٕ آمُت۔ پَنُن ہَنَر کٕنِو پوٗرٕ ہِنٛدُستانَس منٛز تکنیٖکی کمپیوٹر مہارَتہٕ ورٲے۔",
  "literacy.tutorial.step1Title": "1. پننہِ مادری زبانہِ منز کتھ کرو",
  "literacy.tutorial.step1Desc": "ٹایِپ کرنٕچ چھُنہٕ ضروٗرت۔ پنُن فن بیان کرن وول اکھ مختصر وائس نوٹ کٔرِو ریکارڈ۔ سون اے آے چھُ لِسٹنگ نقل کران تہٕ لیکھان۔",
