  "tips.priceFloor": "ہمیشہٕ پننِس خرچَچ حدٕک اُپر قیمت رٕکھِو — خام مال، توٚہنٛد وَقت تہٕ پلیٹ فارم فیس — مَندی ہنٛدِس ماہَس منٛز بہ۔",
  "tips.trackIncome": "ہر اکھ فروخت درج کریو، خٲہ چھُ سٟہٕ ژٕھوٚٹ۔ اکھ آسان آمدنی ریکارڈ تُہیہِ مدد کران چھُ کمزور موسِمَس خٲطرہٕ منصوبہٕ بندی کرنہٕ تہٕ قرضَچ خٲطرہٕ کمٲیہِ ثابت کرنہٕ منٛز۔",
