  "tips.photoQuality": "صاف، لَکَٹِس روشنی منٛز تہٕ کیٚنہہ زٲویَن پؠٹھ ژھٕلنہٕ والہِ فوٹوٗ سٟتی لِسٹنگ چھِ جَلدی فروخت گژھان۔ قدرتی روشنی چھِ فلیشَس نسبَتَن بہتر کٲم کران۔",
  "tips.respondFast": "یٚلہِ توہیِ اکھ دِوَس منٛز سوالَن ہنٛز جواب دِیوان چھِوہٕ تہٕلہِ گاہکَن آرڈر پوٗرہِ کرنہٕچ زیادہٕ اُمید چھیہِ۔",
  "tips.saveSavings": "ہر پیٚسہٕ ہنٛدِس اکھ ژٕھوٚٹ حِصہٕ بچَتَس مَنٛز جدا رٕکھِو — 5% بہ جمع گژھِتھ آرڈرَن درمیان تُہیہِ مدد کران چھُ۔",
  "tips.giPremium": "GI ٹیٚگ چھُ اصل جاٮے ہٕنٛدِس ثبوت یَس پؠٹھ گاہک اعتماد کران چھِ۔ تصدیٖق شُدہٕ سامانَس چھِ اکثر زیادہٕ قیمت مِلان — پننِس سامانَس ہٕنٛدِس قیمتَس کم نہٕ سمجھِو۔",
  "tips.restockEarly": "خام مال ختم گژھنہٕ بریٚح ازلہٕ دوبارہٕ منگاوُن شروٗ کریو، خاصکر تہواروَن تہٕ ژھٕہٕرَاوَن ہٕنٛدِس موسِمَس بریٚح یٚلہِ مانگ بڈھان چھیہِ۔",
  "tips.clusterSupport": "توٚہنٛد کلسٹر رٲبطہٕ کار ہیٖکہِ بلک سامان خرید تہٕ تربیَتَس منٛز مدد کرِتھ — کانٛہہ مسئلہٕ سنٛگین گژھنہٕ بریٚح رٲبطہٕ کریو۔",
  "tips.storySells": "کہٕنی والِن سامانَن خٲطرہٕ چھِ گاہک زیادہٕ پیٚسہٕ دِیوان۔ پننِس تِکنیک یا شِلپَچ تٲریخَس مُتَعلِق اکھ ژٕھوٚٹ نوٗٹ پننِس لِسٹنگَس منٛز شٲمِل کریو۔",
