  "caseStudies.dhamadka-ajrakh.rows.4.after": "کیریئر سکینَس پیٹھ خودکار 48 گٲنٹَن ہُند ایسکرو اَدٲیگی",
  "caseStudies.dhamadka-ajrakh.problem": "واریاہَو ؤریو پٮ۪ٹھٕ چھُ تجارتی فاسٹ فیشن ہاوسَن ہٕنٛدِ ذٔریعہٕ درآمد کرنہٕ آمٕتۍ مصنوعی کیمیٲیی بلاک پرنٹَر دھماڈکاہَس منٛز مستند ہینڈ بلاک پرنٹرَن سٮ۪ٹھاہ کم کٔرمٕتۍ۔ کیمیٲیی متبادلن کوٚر 20 فیصد قۭمتس پیٚٹھ مارکیٹن منٛز سہلاب، ییٚمہ سۭتۍ روایتی آقاؤں قدیم 16 مرحلن ہٕنٛز نباتاتی مزاحمتی تکنیکہٕ کمزور کرنس پیٚٹھ مجبوٗر گٔیہٕ۔",
  "caseStudies.dhamadka-ajrakh.intervention": "کلاکریتی کہِ ذٔریعہٕ، کٔر دھماڈکا گلڈن اصلی انڈیگوفیرا ٹنکٹوریا ویٹ فرمینٹیشن تہٕ ایکیشیا عربیکا گم مزاحمتٕچ سپیکٹروسکوپک تصدیق نفاذ۔ پرٮ۪تھ ژوٗرِ تہٕ گز زیچھرس چھُ کلسٹر نیرنہٕ برونٛہہ اکھ ناقابل تبدیل Ed25519 کرپٹوگرافک سیل تہٕ NFC QR ٹیگ میلان۔",
  "caseStudies.dhamadka-ajrakh.impact": "صداقتچ تصدیق دژ گلڈس لگژری ڈیزائن ہاؤسز تہٕ غیر ملکی ثقافتی مشنن براہ راست کٕننک اجازت۔ گھریلو آمدنی منٛز گٔیہٕ 3.37 گنہٕ اضافہٕ، یمہٕ سۭتۍ اکھ اجتمٲعی قدرتی ڈائی سیڈ بینک تہٕ 14 نوجوان پرنٹرن خٲطرٕ اپرنٹس شپ فنڈ بناونس قٲبل گٔیہٕ۔",
  "caseStudies.dhamadka-ajrakh.quote.text": "ییٚلہِ خٔریٖدار سانہِ پلو وُچھان چھِ تہٕ نیل واٹس منٛز سون اتھہٕ وُچھان چھِ، تِم چھِ سمجھان زِ 16 مرحلن منٛز کیازِ ہٮ۪کو نہٕ جلدٕی کٔرِتھ۔ کالاکریتی کٔر سون عزت بحال۔",
  "caseStudies.dhamadka-ajrakh.quote.author": "اسماعیل محمد کھتری",
