  "caseStudies.varanasi-kadwa.problem": "وارانَسیَس منٛز ٲسۍ ماسٹر زری وونٛنہٕ وٲلہِ واریاہن درجَن ہِنٛدِس بازرَس پٮ۪ٹھ دارمدار یِمَو 35-40 فیصد پرچوُن مارجن برقرار تھٲوِتھ تہٕ 9 رٮ۪تَن تام ادٲیگی منٛز ژیر کٔرِتھ، ییٚمہِ کِنۍ خاندانَن وَہرٲژ ہُنٛد قَرٕض گٔیہِ۔",
  "caseStudies.varanasi-kadwa.intervention": "کالاکریتی ہٕنٛدِ ادارٕ جاتی خریدٲری ہبَن دِیُت ریاستی سربراہی اجلاس، مہمان نوازی گروپَن تہٕ کارپوریٹ تحفہٕ دِنہٕ وٲلۍ کنسورشیاہن پریوار بنکر ایس ایچ جی یَس سۭتۍ براہ راست اجتمٲعی بلک آرڈر دِنُک اجازت۔ پیمنٹ ایسکرو چھُ لوم میلسٹون کِس تصدیٖقَس پیٹھ براہ راست ڈی بی ٹی ٹرانسفر سۭتۍ خودکار گژھان۔",
  "caseStudies.varanasi-kadwa.impact": "سوزنہٕ پتہٕ 48 گٲنٛٹَن انٛدر انٛدر ونٛنہٕ والٮ۪ن تام کُل 1.48 کرور رۄپیہِ ہُنٛد بٲگراونہٕ آمُت۔ 86 پٹ لوم چھِ وۄنۍ 12 رٮ۪تن ہٕنٛدِس ایڈوانس سایکلَن منٛز مُستقل طور بُک کرنہٕ آمٕتۍ، ییٚمہِ سۭتۍ موسمی غریبی پوٗرٕ پٲٹھۍ ختٕم گٔیہِ۔",
  "caseStudies.varanasi-kadwa.quote.text": "ترٮ۪ن نسلن تام وُچھ نہٕ اسہِ زانہہ حتمی خٔریٖدارُک بُتھ۔ وۅنۍ چھُ سون ناو تہٕ لوم پرٮ۪تھ سٲڑۍ سٍتۍ سفر کران۔",
