  "caseStudies.bastar-lost-wax.problem": "غیر مستحکم ترٛام تہٕ زنک سکریپ قۭمتَن بَنوو قبیٖلہٕ دھوکرا مجسمہٕ سازن خٲطرٕ خام موم، میژِ تہٕ دھات کاسٹ کرُن تقریباً ناممکن، ییٚمہِ سۭتۍ انسانیتُک ساروٕے کھۄتہٕ قٔدیٖم غٲر فیرس کاسٹنگ نسبو ختم کرنُک خطرٕ چھُ۔",
  "caseStudies.bastar-lost-wax.intervention": "پلیٹ فارمَن کوٚر خام مال انوینٹری کریڈٹ متعارف یِم ادارٕ جاتی سربراہی اجلاسٕچ خریداری کٹن ہٕنٛز حمایت چھِ۔ مجسمہٕ ساز چھِ پننِس کاریگر ایپس پیٹھ پگھلِتھ ڈالنُک ریکارڈ کران، یُس غٲر ملاوٹ بیل دھاتی مرکب ثٲبت کران چھُ۔",
  "caseStudies.bastar-lost-wax.impact": "28 نٔوۍ قبٲیلی اپرنٹس چھِ کونڈاگاؤں بھٹن منٛز شٲمِل گٔمٕتۍ۔ بستر لوسٹ موم مجسمہٕ چھِ وۄنۍ پوٗرٕ دنیاہَس منٛز ممتاز ادارٕ جاتی لابی تہٕ سفارتی تحفہٕ زینان۔",
  "caseStudies.bastar-lost-wax.quote.text": "سانٮ۪و آباؤ اجدادو ٲسۍ سال جنگلَو منٛزٕ ماچھِ ہُنٛد موم استعمال کران۔ کالاکریتی چھُ یقینی بناوان زِ سانہِ بھٹہٕ گژھن قرضہٕ کہِ خوفہٕ ورٲے یِنہٕ واجنہِ نسلہِ خٲطرٕ روشن ۔",
  "caseStudies.bastar-lost-wax.quote.author": "بُدھیشور گَڈوا",
  "caseStudies.bastar-lost-wax.quote.role": "سینئر سائر-پرڈیو میٹل ورکر، کونڈاگاؤں",
